class Node:
    def __init__(self,v=0,n=None): self.val=v; self.next=n

def build_list(a):
    d=Node(); p=d
    for x in a: p.next=Node(x); p=p.next
    return d.next

def print_list(h):
    a=[]
    while h: a.append(h.val); h=h.next
    print(*a)

def chain(a,tail=None):
    if not a:return tail
    h=build_list(a); p=h
    while p.next:p=p.next
    p.next=tail; return h

def build_cycle(a,pos):
    h=build_list(a)
    if pos<0:return h
    p=h; ent=None; i=0
    while p.next:
        if i==pos:ent=p
        p=p.next; i+=1
    if i==pos:ent=p
    p.next=ent; return h

from collections import deque
class T:
    def __init__(self,v=0): self.val=v; self.left=self.right=None

def build_tree(v):
    if not v or v[0]=='null':return None
    r=T(int(v[0])); q=deque([r]); i=1
    while q and i<len(v):
        x=q.popleft()
        if i<len(v) and v[i]!='null':x.left=T(int(v[i]));q.append(x.left)
        i+=1
        if i<len(v) and v[i]!='null':x.right=T(int(v[i]));q.append(x.right)
        i+=1
    return r

def find(r,v):
    if not r:return None
    if r.val==v:return r
    return find(r.left,v) or find(r.right,v)

def serialize(r):
    if not r:return []
    q=deque([r]);a=[]
    while q:
        x=q.popleft()
        if x:a.append(str(x.val));q.extend((x.left,x.right))
        else:a.append('null')
    while a and a[-1]=='null':a.pop()
    return a

