class MinStack:
    def __init__(self):
        self.stack = []  # stack：每项为 (当前值, 到当前为止的最小值)
    def push(self, x):  # x：新入栈元素
        self.stack.append((x, min(x, self.getMin()) if self.stack else x))
    def pop(self):
        self.stack.pop()
    def top(self):
        return self.stack[-1][0]
    def getMin(self):
        return self.stack[-1][1]

def main():
    q = int(input())  # q：操作次数
    ops = [input().split() for _ in range(q)]  # ops：已经拆分好的操作与参数
    obj = MinStack()  # obj：最小栈对象
    for op, *args in ops:  # op：操作名；args：操作参数
        if op == 'push': obj.push(int(args[0]))
        elif op == 'pop': obj.pop()
        elif op == 'top': print(obj.top())
        else: print(obj.getMin())

