from heapq import heappush, heappop, heappushpop

class MedianFinder:
    def __init__(self):
        self.small, self.large = [], []  # small：较小一半（取负数存堆）；large：较大一半
    def addNum(self, x):  # x：新加入的数据
        heappush(self.large, -heappushpop(self.small, -x))
        if len(self.large) > len(self.small):
            heappush(self.small, -heappop(self.large))
    def findMedian(self):
        if len(self.small) > len(self.large): return -self.small[0]
        return (self.large[0] - self.small[0]) / 2

def main():
    q = int(input())  # q：操作次数
    obj = MedianFinder()  # obj：维护数据流中位数的对象
    for _ in range(q):
        op, *args = input().split()  # op：操作名；args：操作参数
        if op == 'add': obj.addNum(int(args[0]))
        else: print(obj.findMedian())

main()

