import torch.nn.functional as F

# logits：词表分数 [B,L,V]；labels：标签 [B,L]；ignore：忽略标签值
def sft_loss(logits, labels, ignore=-100):
    logits = logits[:, :-1].reshape(-1, logits.size(-1))  # logits：去掉末位置后展平的预测分数
    labels = labels[:, 1:].reshape(-1)  # labels：去掉首位置后展平的下一词标签
    return F.cross_entropy(logits, labels, ignore_index=ignore)

import torch
import torch.nn.functional as F

# pi_c/pi_r：策略模型偏好/非偏好回答的对数概率
def dpo_loss(pi_c, pi_r, ref_c, ref_r, beta=0.1):
    # ref_c/ref_r：参考模型的对应对数概率；beta：偏好强度
    return -F.logsigmoid(beta * ((pi_c - pi_r) - (ref_c - ref_r))).mean()

# new_logp/old_logp：新旧 token 对数概率；reward：组内奖励；eps：裁剪宽度
def grpo_loss(new_logp, old_logp, reward, eps=0.2):
    # adv：标准化奖励，即组内优势 [G,1]
    adv = ((reward - reward.mean()) / (reward.std(unbiased=False) + 1e-8))[:, None]
    ratio = (new_logp - old_logp).exp()  # ratio：新策略概率 / 旧策略概率
    return -torch.minimum(ratio * adv, ratio.clamp(1 - eps, 1 + eps) * adv).mean()

import torch.nn.functional as F

# q：查询向量 [B,D]；gallery：候选库 [N,D]；k：返回候选数
def retrieve(q, gallery, k):
    q, gallery = F.normalize(q, dim=-1), F.normalize(gallery, dim=-1)
    return (q @ gallery.T).topk(k, dim=-1)
